css:
.button {
  --button-col: #e8e8e8;
  --border-size: 5px;
  --rad: 5px;
  --corner-size: 24px;
  --corner-dist: 24px;
  --corner-col: #000c;

  position: relative;
  cursor: pointer;
  padding: 0.75rem 1rem;

  background-color: var(--button-col);
  border-radius: var(--rad);
  border: 1px solid color-mix(in oklab, var(--corner-col) 20%, #0000 80%);

  transition: 0.15s ease;
}

.button .txt {
  display: inline-flex;
  font-size: 1.1rem;
  font-family: "Inter", "Segoe UI", sans-serif;
  color: var(--corner-col);
}
.button .txt .letter {
  opacity: 0.4;
  transition: opacity 0.1s ease;
  transition-delay: calc(0.02s * var(--i));
  transform: rotateX(0);
}
.button .txt .letter.bold {
  font-weight: bold;
}
.button .txt .letter.lighter {
  font-weight: 300;
}

.button::before {
  pointer-events: none;
  content: "";
  position: absolute;
  inset: calc(-1 * var(--border-size));
  z-index: -1;
  border-radius: calc(var(--border-size) + var(--rad));

  background-color: color-mix(in oklab, var(--corner-col) 10%, #0000 90%);
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--corner-col) 30%, #0000 70%),
    inset 0 1px 2px -1px var(--corner-col);
}

.corner {
  pointer-events: none;
  position: absolute;
  height: var(--corner-size);
  width: var(--corner-size);
  fill: var(--corner-col);
  transition: 0.15s ease;
}

.corner.top {
  top: calc(-1 * var(--corner-dist));
}
.corner.bottom {
  bottom: calc(-1 * var(--corner-dist));
}
.corner.left {
  left: calc(-1 * var(--corner-dist));
}
.corner.right {
  right: calc(-1 * var(--corner-dist));
}

.rot-90 {
  rotate: 90deg;
}
.rot-180 {
  rotate: 180deg;
}
.rot-270 {
  rotate: 270deg;
}

/*hover*/
.button:hover {
  --corner-dist: 20px;
  .txt .letter {
    opacity: 1;
    animation: anim ease 0.1s forwards;
    animation-delay: calc(0.03s * var(--i));
  }
}
@keyframes anim {
  50% {
    transform: rotateX(60deg);
  }
}

/*active*/
.button:active {
  --corner-dist: 16px;
}
